# all compositions of 7 into 3 contiguous row/col groups
def compositions(n, k):
    if k == 1:
        yield (n,); return
    for first in range(1, n - k + 2):
        for rest in compositions(n - first, k - 1):
            yield (first,) + rest

comps = list(compositions(7, 3))

def blocks(rsplit, csplit):
    rb, cb = [], []
    s = 0
    for x in rsplit: rb.append((s, s+x)); s += x
    s = 0
    for x in csplit: cb.append((s, s+x)); s += x
    return rb, cb

def test_pred(pred):
    """pred(block_cells 2D list, ri, ci) -> bool (8 or 0)"""
    for rin, cout in [(demo1_in, demo1_out), (demo2_in, demo2_out)]:
        for rsplit in comps:
            for csplit in comps:
                rb, cb = blocks(rsplit, csplit)
                ok = True
