                    for j in range(3):
                        cells = [rin[r][c] for r in range(rb[i][0], rb[i][1]) for c in range(cb[j][0], cb[j][1])]
                        want = 8 if cout[i][j] == 8 else 0
                        if (8 if pred(cells) else 0) != want:
                            ok = False; break
                    if not ok: break
                if ok:
                    return (rsplit, csplit)
    return None

