def down_pos(cells_idx, rsplit, csplit):
    rb = blocks(7, rsplit); cb = blocks(7, csplit)
    def ri(r):
        for i,(a,b_) in enumerate(rb):
            if a <= r < b_: return i
    def cj(c):
        for j,(a,b_) in enumerate(cb):
            if a <= c < b_: return j
    return set((ri(r), cj(c)) for r,c in cells_idx)

