    if f=='nb': return sum(1 for r in blk for c in r if c!=b)
    if f=='nb_nz': return sum(1 for r in blk for c in r if c!=b and c!=0)
    if f=='z': return sum(1 for r in blk for c in r if c==0)
    if f=='b': return sum(1 for r in blk for c in r if c==b)
    if f=='distinct_nb': return len(set(c for r in blk for c in r if c!=b))
    if f=='distinct_nz': return len(set(c for r in blk for c in r if c!=b and c!=0))
    if f=='sum_nb': return sum(c for r in blk for c in r if c!=b)
    if f=='mx': return max(c for r in blk for c in r if c!=b) if any(c!=b for r in blk for c in r) else -1

