    Scells = [(r,c) for r in range(7) for c in range(7) if g[r][c]==Sc]
    def bbox(cs):
        if not cs: return (0,0)
        rs=[r for r,c in cs]; cl=[c for r,c in cs]; return (max(rs)-min(rs)+1, max(cl)-min(cl)+1)
    return {
      'bgcnt':bgcnt,'Scnt':Scnt,'nz':nz,'nsp':nsp,'bg-S':bgcnt-Scnt,'nspS':nsp+Scnt,
      'ncol':len(cnt),'nones':sum(1 for c,n in sp.items() if n==1),'npairs':sum(1 for c,n in sp.items() if n==2),
      'bgncol':bgcnt-len(cnt),'S-nsp':Scnt-nsp,'nz-nsp':nz-nsp,'nz-Scnt':nz-Scnt,
      'bboxsp':bbox(spcells),'bboxS':bbox(Scells),'bboxnz':bbox([(r,c) for r in range(7) for c in range(7) if g[r][c]!=b]),
      'Spairs':sum(1 for c,n in cnt.items() if n==2),'Sones':sum(1 for c,n in cnt.items() if n==1),
      'minc':min(n for n in cnt.values()),'maxc':mc[0][1],'maxcol':mc[0][0],'Scol':Sc,
    }
